  CheckThat("current result cats preserve eight frames and duration",VictoryCatAnimation.FrameCount==8&&FailureCatAnimation.FrameCount==8&&ResultsC048Art.FrameAt(true,1.91f)==7&&ResultsC048Art.FrameAt(false,2.31f)==7);
  SelectCurrent("victory");yield return new WaitForSecondsRealtime(2.6f);var victory=(VictoryPresentation)gallery.CurrentComponent;CheckThat("current victory surface and eight-frame cat render",victory.Surface.LayoutFits&&victory.CatFrame==7&&victory.Ready&&victory.HeaderStars.Length==3);
  SelectCurrent("failure");yield return new WaitForSecondsRealtime(2.6f);var lose=(FailurePresentation)gallery.CurrentComponent;CheckThat("current failure surface and eight-frame cat render",lose.Surface.LayoutFits&&lose.CatFrame==7&&lose.Ready);
 }
